/bin/bash -lc "python - <<'PY'
import urllib.request,urllib.error,os
for url in ['https://api.assemblyai.com/v2/transcript?limit=1','https://www.assemblyai.com/docs/audio-intelligence/pii-redaction','https://raw.githubusercontent.com/AssemblyAI/assemblyai-python-sdk/master/assemblyai/types.py']:
 try:
  req=urllib.request.Request(url,headers={'Authorization':os.environ['ASSEMBLYAI_API_KEY']} if url.startswith('https://api.') else {})
  with urllib.request.urlopen(req,timeout=20) as r:
   b=r.read();print(url,r.status,len(b))
   if 'types.py' in url:open('/tmp/aai-types.py','wb').write(b)
   elif '/docs/' in url:open('/tmp/aai-pii.html','wb').write(b)
 except Exception as e:print(url,type(e).__name__,str(e))
PY"

